const cliArgs = process.argv.slice(2);
const isRollback = cliArgs.includes("--rollback");
const isDryRun = cliArgs.includes("--dry-run");
const dirFlagIdx = cliArgs.indexOf("--dir");

function resolveTargetRoot() {
  if (dirFlagIdx !== -1 && cliArgs[dirFlagIdx + 1]) {
    return path.resolve(cliArgs[dirFlagIdx + 1]);
  }
  const cwd = process.cwd();
  if (path.basename(cwd) === "patches") {
    return path.resolve(cwd, "..");
  }
  return cwd;
}

function sha256Buffer(buf) {
  return crypto.createHash("sha256").update(buf).digest("hex");
}

const targetRoot = resolveTargetRoot();
const backupDir = path.join(targetRoot, ".patch-backups", `phase-${PHASE}`);
const backupMetaPath = path.join(backupDir, "backup-meta.json");
const stateFilePath = path.join(targetRoot, ".omniflow-patch-state.json");

if (isRollback) {
  if (!fs.existsSync(backupMetaPath)) {
    console.error(`[OmniFlow Patcher] No backup metadata found at ${backupMetaPath}. Cannot rollback Phase ${PHASE}.`);
    process.exit(1);
  }
  const meta = JSON.parse(fs.readFileSync(backupMetaPath, "utf8"));
  for (const createdRel of meta.createdFiles || []) {
    const abs = path.join(targetRoot, createdRel);
    if (fs.existsSync(abs)) fs.rmSync(abs, { force: true });
  }
  for (const backedUpRel of meta.overwrittenFiles || []) {
    const src = path.join(backupDir, "files", backedUpRel);
    const dest = path.join(targetRoot, backedUpRel);
    if (fs.existsSync(src)) {
      fs.mkdirSync(path.dirname(dest), { recursive: true });
      fs.copyFileSync(src, dest);
    }
  }
  console.log(`[OmniFlow Patcher] Successfully rolled back Phase ${PHASE} (${PHASE_TITLE}).`);
  process.exit(0);
}

console.log(`\n======================================================================`);
console.log(` OmniFlow Patcher — Applying Phase ${PHASE} of 7: ${PHASE_TITLE}`);
console.log(` Target Directory: ${targetRoot}`);
console.log(`======================================================================\n`);

const createdFiles = [];
const overwrittenFiles = [];

if (!isDryRun) {
  fs.mkdirSync(path.join(backupDir, "files"), { recursive: true });
}

for (const relDelete of FILES_TO_DELETE) {
  const absDelete = path.join(targetRoot, relDelete);
  if (fs.existsSync(absDelete)) {
    overwrittenFiles.push(relDelete);
    if (!isDryRun) {
      const bkpDest = path.join(backupDir, "files", relDelete);
      fs.mkdirSync(path.dirname(bkpDest), { recursive: true });
      fs.copyFileSync(absDelete, bkpDest);
      fs.rmSync(absDelete, { force: true });
    }
    console.log(`  [DELETE] ${relDelete}`);
  }
}

for (const entry of MANIFEST) {
  const absPath = path.join(targetRoot, entry.path);
  const existed = fs.existsSync(absPath);
  const buffer = Buffer.from(entry.base64, "base64");

  const computedHash = sha256Buffer(buffer);
  if (computedHash !== entry.sha256) {
    console.error(`[ERROR] Integrity mismatch before writing ${entry.path}`);
    process.exit(1);
  }

  if (existed) {
    overwrittenFiles.push(entry.path);
    if (!isDryRun) {
      const bkpDest = path.join(backupDir, "files", entry.path);
      fs.mkdirSync(path.dirname(bkpDest), { recursive: true });
      fs.copyFileSync(absPath, bkpDest);
    }
  } else {
    createdFiles.push(entry.path);
  }

  if (!isDryRun) {
    fs.mkdirSync(path.dirname(absPath), { recursive: true });
    fs.writeFileSync(absPath, buffer);

    // Post-write disk verification
    const diskHash = sha256Buffer(fs.readFileSync(absPath));
    if (diskHash !== entry.sha256) {
      console.error(`[ERROR] Disk verification failed for ${entry.path}`);
      process.exit(1);
    }
  }

  console.log(`  [${existed ? "UPDATE" : "CREATE"}] ${entry.path} (${entry.size} bytes) ✓`);
}

if (!isDryRun) {
  fs.writeFileSync(
    backupMetaPath,
    JSON.stringify(
      {
        phase: PHASE,
        title: PHASE_TITLE,
        appliedAt: new Date().toISOString(),
        createdFiles,
        overwrittenFiles,
      },
      null,
      2
    ),
    "utf8"
  );

  let prevHistory = [];
  if (fs.existsSync(stateFilePath)) {
    try {
      const prev = JSON.parse(fs.readFileSync(stateFilePath, "utf8"));
      prevHistory = Array.isArray(prev.history) ? prev.history : [];
    } catch {
      prevHistory = [];
    }
  }

  fs.writeFileSync(
    stateFilePath,
    JSON.stringify(
      {
        currentPhase: PHASE,
        phaseTitle: PHASE_TITLE,
        updatedAt: new Date().toISOString(),
        history: [
          ...prevHistory,
          {
            phase: PHASE,
            title: PHASE_TITLE,
            appliedAt: new Date().toISOString(),
            createdCount: createdFiles.length,
            updatedCount: overwrittenFiles.length,
          },
        ],
      },
      null,
      2
    ),
    "utf8"
  );
}

console.log(`\n----------------------------------------------------------------------`);
console.log(` Phase ${PHASE} Patch Summary:`);
console.log(`   Created : ${createdFiles.length} file(s)`);
console.log(`   Updated : ${overwrittenFiles.length} file(s)`);
console.log(`   Verified: ${MANIFEST.length} SHA-256 checksum(s) passed`);
console.log(`   Rollback: node phase-${PHASE}-patcher.mjs --rollback`);
console.log(`----------------------------------------------------------------------`);
console.log(` Next Steps:`);
console.log(`   1. npm install`);
